trial.program_source:
def transform(grid):
    a=[r[:] for r in grid]
    shots={(r,c) for r,row in enumerate(a) for c,x in enumerate(row) if x==6}
    for r,c in shots:
        a[r][c]=0
        for y in range(r-1,-1,-1):
            if a[y][c]==9:
                l=c
                h=c
                while l>0 and a[y][l-1]==9:l-=1
                while h+1<len(a[0]) and a[y][h+1]==9:h+=1
                for x in range(l,h+1):a[y][x]=0
                break
    return a

